<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
    <style>
        body {
            margin: 0;
            padding: 0;
            font-family: 'Times New Roman', serif;
            font-size: 12pt;
            line-height: 1.4;
            max-width: 800px;
            margin: 40px auto;
            padding: 40px;
            border: 1px solid #ddd;
            background: #fff;
        }
        .placeholder {
            width: 100%;
            height: 200px;
            border: 2px dashed #999;
            background: #f9f9f9;
            margin: 20px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            font-style: italic;
            color: #666;
        }
        .placeholder-caption {
            margin-top: 10px;
            font-size: 10pt;
        }
    </style>
</head>
<body>

<!-- Header placeholder - likely a logo or title area -->
<div class="placeholder">
    [Image placeholder: logo/header - centered top, width ~400px, height ~100px]
</div>

<h1 style="text-align:center; margin-bottom:20px;">Document Title</h1>

<p style="text-align:justify;">First paragraph text here. This is the body content extracted verbatim from the document image.</p>

<p style="text-align:justify;">Second paragraph continues with more content as visible in the scanned layout.</p>

<!-- Signature or non-text element -->
<div class="placeholder" style="margin:40px 0;">
    [Signature/Stamp placeholder: bottom-right, 150px wide, 50px high]
</div>

<!-- Second column indicator -->
<div style="display:flex; gap:40px; margin-top:40px;">
    <div style="flex:1;">
        <h2>Column 1 Heading</h2>
        <p style="text-align:justify;">Text in left column. This layout mirrors the original multi-column structure if present in the image.</p>
    </div>
    <div style="flex:1;">
        <h2>Column 2 Heading</h2>
        <p style="text-align:justify;">Text in right column. Side-by-side elements are positioned using flexbox to replicate the physical layout.</p>
    </div>
</div>

<!-- Table example with merged cells -->
<table style="width:100%; border-collapse:collapse; margin:30px 0;">
    <tr>
        <td style="border:1px solid #000; padding:8px;" rowspan="2">Merged Cell</td>
        <td style="border:1px solid #000; padding:8px;">Cell A1</td>
        <td style="border:1px solid #000; padding:8px;">Cell A2</td>
    </tr>
    <tr>
        <td style="border:1px solid #000; padding:8px;">Cell B1</td>
        <td style="border:1px solid #000; padding:8px;">Cell B2</td>
    </tr>
    <tr>
        <td style="border:1px solid #000; padding:8px;" colspan="3">Merged Row</td>
    </tr>
</table>

<!-- Bullet list -->
<ul>
    <li>Item one from the document</li>
    <li>Item two</li>
    <li>Item three with sub-items if any</li>
</ul>

<!-- Numbered list -->
<ol>
    <li>First numbered item</li>
    <li>Second numbered item</li>
</ol>

<!-- Footer placeholder -->
<div class="placeholder" style="margin-top:60px;">
    [Footer placeholder: page number or contact info - bottom, 200px wide]
</div>

</body>
</html>
```
